// ─────────────────────────────────────────────────────────────────────────
//  01 · top customers★★☆ core
//  concepts: Where · GroupBy · OrderBy/ThenBy · ToList
// ─────────────────────────────────────────────────────────────────────────
//
//  Filter, group, order, take: then materialise once.

using static Bootcamp.Check;

IReadOnlyList<CustomerTotal> TopCustomers(IEnumerable<Order> orders, int n) =>
    orders
        .Where(o => o.Status == "paid")
        .GroupBy(o => o.Customer)
        .Select(g => new CustomerTotal(g.Key, g.Sum(o => o.Total)))
        .OrderByDescending(c => c.Total)
        .ThenBy(c => c.Customer, StringComparer.Ordinal)
        .Take(n)
        .ToList();

// ──────────────────────────── tests ──────────────────────────────────────

Test("sums paid orders per customer", () =>
{
    var orders = new List<Order> { new("ana", 50m, "paid"), new("bo", 70m, "paid"), new("ana", 30m, "paid"), new("bo", 999m, "refunded") };
    Eq(TopCustomers(orders, 10), new[] { new CustomerTotal("ana", 80m), new CustomerTotal("bo", 70m) });
});

Test("ties are broken by customer name", () =>
{
    var orders = new List<Order> { new("cy", 10m, "paid"), new("al", 10m, "paid"), new("bo", 20m, "paid") };
    Eq(TopCustomers(orders, 3).Select(c => c.Customer).ToList(), new[] { "bo", "al", "cy" });
});

Test("at most n results", () =>
{
    var orders = new List<Order> { new("a", 1m, "paid"), new("b", 2m, "paid"), new("c", 3m, "paid") };
    Eq(TopCustomers(orders, 2).Count, 2);
});

Test("the result is a snapshot of the source", () =>
{
